<script setup>import MButton from '../../../components/mds/MButton.vue';import MEmptyState from '../../../components/mds/MEmptyState.vue';import MTag from '../../../components/mds/MTag.vue';defineProps({rows:{type:Array,default:()=>[]},canViewAudit:Boolean,canViewVisibility:Boolean,canCreate:Boolean,canEdit:Function,canDelete:Function});const emit=defineEmits(['audit','visibility','create','edit','delete']);</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><h1 class="text-[20px] font-semibold">Quản trị hệ thống</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách người dùng. Quyền cuối cùng luôn do máy chủ kiểm tra.</p></header><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="flex items-center justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><h2 class="text-[15px] font-semibold">Người dùng và phân quyền</h2><div class="flex items-center gap-2"><MButton v-if="canViewVisibility" variant="secondary" @click="emit('visibility')">Hiển thị trường</MButton><MButton v-if="canViewAudit" variant="secondary" @click="emit('audit')">Nhật ký audit</MButton><MButton v-if="canCreate" variant="primary" @click="emit('create')">Thêm người dùng</MButton></div></header><MEmptyState v-if="!rows.length" title="Chưa có người dùng" description="Máy chủ chưa trả người dùng được phép xem."/><table v-else class="w-full text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Tài khoản</th><th class="px-3 py-3">Họ tên</th><th class="px-3 py-3">Email</th><th class="px-3 py-3">Vai trò</th><th class="px-3 py-3">Trạng thái</th><th class="px-5 py-3 text-right">Thao tác</th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="user in rows" :key="user.id"><td class="px-5 py-3 text-[13px] font-medium">{{ user.username }}</td><td class="px-3 py-3 text-[13px]">{{ user.fullName }}</td><td class="px-3 py-3 text-[13px]">{{ user.email || '—' }}</td><td class="px-3 py-3"><MTag color="brand">{{ user.roleLabel }}</MTag></td><td class="px-3 py-3"><MTag :color="user.active?'success':'neutral'">{{ user.active?'Hoạt động':'Khóa' }}</MTag></td><td class="px-5 py-3"><div class="flex justify-end gap-2"><MButton v-if="canEdit?.(user)" variant="link" @click="emit('edit',user)">Sửa</MButton><MButton v-if="canDelete?.(user)" variant="link" class="[&]:text-[var(--mds-danger)]" @click="emit('delete',user)">Xóa</MButton></div></td></tr></tbody></table></section></div></section></template>
